					//uptodate flag
					xjcTask.getOutputs().file(new File(outputDirectory,"JAXB."+taskName+".generated").getAbsolutePath());
					xjcTask.getOutputs().upToDateWhen({	
						return new File(outputDirectory,"JAXB."+taskName+".generated").exists();
					});


