    @email = params[:email]
    @token = params[:token]
    @magic_link = auth_callback_url(:magiclink, token: @token)

    mail to: @email, subject: 'Návody.Digital: Odkaz na prihlásenie'
  end
end

class StaticController < ApplicationController

  def index
    @faqs = Page.faq.all # TODO: fetch top FAQs here
    @journeys = Journey.published
  end

  def show
    @page = Page.where(is_faq: false).find_by!(slug: params[:id])
  end
end

